  own += (vec3(1.0, 0.07, 0.05) * (u_lightsA.y * 0.14) + vec3(u_lightsA.z * 1.3)) * (max(dot(n, L * inversesqrt(d2 + 0.0001)), 0.0) / (1.0 + d2 * 0.5));
